import 'package:flutter/material.dart';
import '../../data/models/models.dart';
import '../../data/sample/sample_data.dart';
class ExerciseScreen extends StatefulWidget { final Lesson lesson; const ExerciseScreen({super.key,required this.lesson}); @override State<ExerciseScreen> createState()=>_ExerciseScreenState(); }
class _ExerciseScreenState extends State<ExerciseScreen>{int? selected;bool corrected=false;@override Widget build(BuildContext context){final items=demoExercises.where((e)=>e.lessonId==widget.lesson.id).toList();return Scaffold(appBar:AppBar(title:const Text('Exercices')),body:items.isEmpty?const Center(child:Text('Les exercices arrivent bientôt.')):ListView(padding:const EdgeInsets.all(20),children:items.map((e)=>Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(e.question,style:const TextStyle(fontSize:19,fontWeight:FontWeight.bold)),const SizedBox(height:14),...List.generate(e.options.length,(i)=>RadioListTile<int>(value:i,groupValue:selected,onChanged:corrected?null:(v)=>setState(()=>selected=v),title:Text(e.options[i]))),FilledButton(onPressed:selected==null||corrected?null:()=>setState(()=>corrected=true),child:const Text('Vérifier ma réponse')),if(corrected)Padding(padding:const EdgeInsets.only(top:14),child:Text('${selected==e.correctIndex?'Bonne réponse !':'Pas tout à fait.'} ${e.explanation}',style:const TextStyle(fontWeight:FontWeight.w600)))] )).toList()));}}
